# Verb Forms, part B (DLI Grammar Reference Book II, Lessons 93–103): active participles, -ся passive, present passive participles, деепричастия.
from kit import *

SRC = "From the DLI Grammar Reference Book"

SECTIONS = [

SEC("f5-present-active", "Present active participles: читающий", sub="DLI Lesson 93 · -щий · -щийся · declension · который", blocks=[
  P("Participles are \"verbal adjectives\". The long form of the past passive participle denotes the (direct) object of someone's action. The active participle is also a long form adjective, but it always denotes the performer of the action: *пишущий студент* = студент, который пишет (who writes); *писавший студент* = студент, который писал (who was writing)."),
  P("There are: 1. Present active participles formed from the present tense of imperfective verbs. 2. Past active participles formed from the past tenses of both imperfective and perfective verbs. No participles are formed from future tenses. All active participles are used only as modifiers; they have no short forms."),
  H("Formation"),
  P("a) Present active participles are formed from the 3rd person plural of the present tense by replacing the last -т of the verb by -щ plus adjectival ending: (они) работают — работающий, работающая, работающее, работающие; (они) говорят — говорящий, говорящая, говорящее, говорящие. b) From -ся verbs the particle -ся (never -сь!) is added to the ending: моются — моющийся, моющаяся, моющееся, моющиеся. c) In almost all present active participles the stress is the same as in the 3rd person plural, with the exception of мочь — могущий and a group of 2nd-conjugation verbs in which the stress coincides with the infinitive: курящий, носящий, смотрящий, находящийся."),
  H("Declension and use"),
  P("Present active participles are declined like adjectives and always agree in gender, number and case with the word modified: *Я вижу сидящую девушку. Мы говорим с отъезжающими офицерами.* If used singly, the participle always precedes the modified word: *спящий человек; горящее здание.* A participial phrase may be placed before or after the modified word. In the «который» clauses which replace present active participial phrases, «который» will always be the subject of the clause (in the nominative case), the verb being in the present tense:"),
  EX(("Сюда придут студенты, кончающие школу через месяц. = …которые кончают школу через месяц.", ""), ("Дайте это студентам, кончающим школу через месяц.", ""), ("Поговорите со студентами, кончающими школу через месяц.", "")),
  NOTE("DLI, Lesson 93."),
], exercises=[
  FILL("(они) работают → ___ (masc.)", ["работающий"], SRC + ", Lesson 93."),
  FILL("(они) говорят → ___ (fem.)", ["говорящая"], SRC + ", Lesson 93."),
  MC("мыться → (masc.)", ["моющийсь", "моющийся"], 1, "-ся (never -сь!) is added. " + SRC + ", Lesson 93."),
  FILL("мочь → ___ (masc.)", ["могущий"], SRC + ", Lesson 93."),
  FILL("Я вижу ___ девушку. (сидеть)", ["сидящую"], SRC + ", Lesson 93."),
  FILL("Мы говорим с ___ офицерами. (отъезжать)", ["отъезжающими"], SRC + ", Lesson 93."),
  FILL("___ здание (гореть)", ["горящее"], SRC + ", Lesson 93."),
  FILL("Дайте это студентам, ___ школу через месяц. (кончать)", ["кончающим"], SRC + ", Lesson 93."),
  MC("Сюда придут студенты, ___ кончают школу через месяц.", ["которых", "которые"], 1, "«который» is always the subject of such a clause. " + SRC + ", Lesson 93."),
  MC("Participles from the future tense…", ["are formed with -щий", "are not formed"], 1, "No participles are formed from future tenses. " + SRC + ", Lesson 93."),
]),

SEC("f6-past-active", "Past active participles: прочитавший, принёсший, шедший", sub="DLI Lessons 94–95 · -вший · -ший · идти, вести · оба", blocks=[
  P("The past active participle, like the present active participle, is a verbal adjective; it denotes the performer of an action which took place in the past. It can be formed both from perfective and imperfective verbs: *писавший* = который писал; *написавший* = который написал."),
  H("Formation"),
  P("Group 1: verbs ending in -л in the past tense. The participle is formed from the past tense (masculine) by dropping -л and adding the suffix -вш- before the adjectival ending: проверял — проверявший; проверил — проверивший. From -ся verbs, -ся (never -сь) is added after the adjectival ending: мылся — мывшийся."),
  P("Group 2: verbs ending in the past tense (masc.) in any other consonant but -л add the suffix -ш- + adjectival ending: принёс — принёсший; погиб — погибший; спасся — спасшийся. Exception: исчезнуть — исчез — исчезнувший."),
  P("Group 3: the verb идти with its derivatives and some verbs in -сти change the -л of the past tense to д or т (appearing in the present stem) before -ший: идти (иду) — шедший; вести (веду) — ведший; изобрести (изобрету) — изобретший. The same in derivatives: прийти — пришедший; перевести — переведший."),
  P("The stress coincides with that of the past tense (masculine)."),
  H("Use"),
  P("Past active participles: 1) do not have short forms; 2) are used only as modifiers, agreeing in gender, number and case with the word modified; 3) are declined like adjectives; 4) when used alone always precede the word modified; 5) can form participial phrases which may be located before or after the word modified."),
  EX(("Упавший самолёт летел из Киева.", ""), ("Мы подошли к упавшему самолёту.", ""), ("На упавшем самолёте летел мой начальник.", ""), ("Лётчик, прилетевший вчера из Арктики, привёз важные сведения.", "")),
  P("Participial phrases can be replaced by «который» clauses, in which «который» is a subject and the verb is in the past tense: *Генерал наградил лётчика, сбившего два самолёта = который сбил два самолёта. В вагонах сидели солдаты, возвращавшиеся с фронта = которые возвращались с фронта.* Sometimes the present active participle is used instead, to emphasize simultaneous action: *Вчера мы видели горящий дом.*"),
  H("оба, обе"),
  P("The numerals оба and обе are declined like soft adjectives in the plural: обоих (братьев), обеих (сестёр), обоим, обеим, обоими, обеими, об обоих, об обеих. They agree with the nouns like два — две: *Мы видели оба трактора и обоих шофёров. Передайте эти книги обоим учителям и обеим учительницам.*"),
  NOTE("DLI, Lessons 94 and 95."),
], exercises=[
  FILL("проверил → ___ (masc.)", ["проверивший"], SRC + ", Lesson 94."),
  FILL("писал → ___ (masc.)", ["писавший"], SRC + ", Lesson 94."),
  FILL("принёс → ___ (masc.)", ["принёсший", "принесший"], SRC + ", Lesson 95."),
  FILL("погиб → ___ (masc.)", ["погибший"], SRC + ", Lesson 95."),
  MC("исчезнуть →", ["исчезший", "исчезнувший"], 1, "The exception. " + SRC + ", Lesson 95."),
  MC("идти →", ["идший", "шедший", "шёлший"], 1, SRC + ", Lesson 95."),
  FILL("прийти → ___ (masc.)", ["пришедший"], SRC + ", Lesson 95."),
  FILL("Мы подошли к ___ самолёту. (упасть)", ["упавшему"], SRC + ", Lesson 94."),
  FILL("На ___ самолёте летел мой начальник. (упасть)", ["упавшем"], SRC + ", Lesson 94."),
  FILL("Лётчик, ___ вчера из Арктики, привёз важные сведения. (прилететь)", ["прилетевший"], SRC + ", Lesson 94."),
  FILL("Генерал наградил лётчика, ___ два самолёта. (сбить)", ["сбившего"], SRC + ", Lesson 94."),
  FILL("В вагонах сидели солдаты, ___ с фронта. (возвращаться)", ["возвращавшиеся"], SRC + ", Lesson 94."),
  FILL("Командир говорит о солдате, ___ в бою. (погибнуть)", ["погибшем"], SRC + ", Lesson 94."),
  FILL("Мы видели оба трактора и ___ шофёров.", ["обоих"], SRC + ", Lesson 95."),
  FILL("Передайте эти книги обоим учителям и ___ учительницам.", ["обеим"], SRC + ", Lesson 95."),
]),

SEC("f7-passive-present", "The -ся passive and present passive participles: читается, издаваемый", sub="DLI Lessons 96–97 · imperfective passive · functions of -ся · -емый, -имый", blocks=[
  H("Passive in the imperfective construction"),
  P("The passive in the imperfective can be expressed by a transitive verb to which the -ся ending has been added. The performer of the action is in the instrumental case:"),
  T(["Passive", "Active"], [["Эта книга читается всеми. (is read; is being read)", "Эту книгу читают все."], ["Эта книга читалась всеми. (was read)", "Эту книгу читали все."], ["Эта книга будет читаться всеми.", "Эту книгу будут читать все."], ["Эта книга должна (может) читаться всеми.", "Эту книгу должны (могут) читать все."]], row_heads=False),
  P("Sometimes the actor is not mentioned. Such constructions can often be expressed by impersonal active constructions with the verb in the 3rd person plural: *Рыба подаётся здесь редко. — Рыбу подают здесь редко. Этот вопрос обсуждался вчера. — Этот вопрос обсуждали вчера.*"),
  T(["", "Imperfective: подписывать", "Perfective: подписать"], [
    ["Present", "Такие бумаги обычно подписываются генералом.", "Эти бумаги подписаны генералом."],
    ["Past", "Такие бумаги обычно подписывались генералом.", "Вчера эти бумаги были подписаны генералом."],
    ["Future", "Такие бумаги будут и дальше подписываться генералом.", "Эти бумаги будут подписаны генералом завтра."],
  ]),
  P("The Russian imperfective passive constructions convey the idea of generalization, continuation, repetition or incomplete action."),
  H("Different functions of -ся verbs"),
  EX(("Учитель начинает урок. — Урок начинается.", "intransitive, same meaning"), ("Он моет машину. — Он моется по утрам.", "reflexive"), ("Она познакомила меня с ним. — Мы познакомились.", "reciprocal"), ("Почтальон доставляет почту. — Почта доставляется почтальоном.", "passive"), ("Он хочет спать. — Ему хочется спать.", "impersonal")),
  H("The present passive participle"),
  P("The present passive participle may be encountered quite often in written language, particularly in newspapers. In spoken language, with the exception of a limited number of verbs, it is rarely used. It doesn't have a short form and can only be used as a modifier: *Опыты, производимые нашей лабораторией, очень интересны. Я охотно читаю газету, издаваемую нашей школой.*"),
  P("Formation: a) it is formed by adding adjectival endings to the 1st person plural of the present tense of a transitive imperfective verb: мы описываем — описываемый; мы производим — производимый. b) In the давать group the suffix -ва- is retained: издавать — издаваемый. c) When no present passive participle can be formed, one may be borrowed from a verb close in meaning: ждать — ожидаемый; хотеть — желаемый. d) Some are widely used as adjectives: любимый, уважаемый, непереводимый."),
  P("Most phrases with present passive participles can be replaced by a который clause: *Газета, издаваемая Компартией = которую издаёт Компартия = которая издаётся Компартией.*"),
  NOTE("DLI, Lessons 96 and 97."),
], exercises=[
  FILL("Эту книгу читают все. → Эта книга ___ всеми.", ["читается"], SRC + ", Lesson 96."),
  FILL("Эту книгу читали все. → Эта книга ___ всеми.", ["читалась"], SRC + ", Lesson 96."),
  FILL("Эту книгу будут читать все. → Эта книга будет ___ всеми.", ["читаться"], SRC + ", Lesson 96."),
  FILL("Рыба подаётся здесь редко. → Рыбу ___ здесь редко.", ["подают"], SRC + ", Lesson 96."),
  MC("Такие бумаги обычно ___ генералом. (are usually signed)", ["подписаны", "подписываются"], 1, "The imperfective passive: generalization, repetition. " + SRC + ", Lesson 96."),
  MC("Вчера эти бумаги ___ генералом.", ["были подписаны", "подписывались бы"], 0, SRC + ", Lesson 96."),
  FILL("Почта доставляется ___ по утрам. (почтальон)", ["почтальоном"], SRC + ", Lesson 96."),
  FILL("Учитель начинает урок. — Урок ___ .", ["начинается"], SRC + ", Lesson 96."),
  FILL("Он хочет спать. — Ему ___ спать.", ["хочется"], SRC + ", Lesson 96."),
  FILL("мы описываем → ___ (masc.)", ["описываемый"], SRC + ", Lesson 97."),
  FILL("Опыты, ___ нашей лабораторией, очень интересны. (производить)", ["производимые"], SRC + ", Lesson 97."),
  FILL("Я охотно читаю газету, ___ нашей школой. (издавать)", ["издаваемую"], "In the давать group the suffix -ва- is retained. " + SRC + ", Lesson 97."),
  MC("ждать → present passive participle", ["ждаемый", "ожидаемый"], 1, "Borrowed from a verb close in meaning. " + SRC + ", Lesson 97."),
]),

SEC("f8-gerund-imperfective", "Imperfective деепричастия: читая, говоря", sub="DLI Lessons 100, 102 · -я, -а · -ясь · будучи · when not to use them", blocks=[
  P("The деепричастие is an unchangeable verbal form used within the sentence as a predicate modifier to indicate a supplementary action on the part of the subject. It may be an adverbial modifier denoting the time, reason, condition, manner, etc. and answering the questions когда, почему, как, etc., or it may express the secondary predicate of a sentence:"),
  EX(("Рассказывая мне это, она плакала. = Когда она рассказывала мне это, она плакала.", ""), ("Она рассказывала мне это плача.", "")),
  P("The main and the subordinate clauses have the same actor. The imperfective деепричастие indicates an action simultaneous with the action of the predicate whether the latter is in the present, past or future: *Переписывая домашнюю работу, он делает (делал, будет делать, сделал, сделает) новые ошибки.*"),
  H("Formation"),
  P("a) Imperfective деепричастия are formed by substituting the ending of the 3rd person plural of the present tense (-ют, -ут, -ят, -ат) with -я, or -а after ж, ч, ш, щ: читают — читая; идут — идя; говорят — говоря; служат — служа. The stress in most coincides with that of the first person singular. b) From the derivatives of -ставать, -знавать and -давать they are formed from the infinitives: переставая, узнавая, продавая. c) From -ся verbs the particle -сь (never -ся!) is added: бреются — бреясь; ложатся — ложась."),
  P("Most деепричастия can be replaced by an adverbial clause of time, condition, reason: *Выходя из дома, я услышал выстрел. = Когда я выходил из дома… Занимаясь так мало, вы не выдержите экзамена. = Если вы будете заниматься так мало… Зарабатывая очень мало, он не может купить автомобиля. = Так как он зарабатывает очень мало…*"),
  H("будучи, and verbs without the form"),
  P("The imperfective деепричастие of быть is будучи: *Будучи доктором — being a doctor. Будучи в Москве — while (being) in Moscow.* In some verbs the imperfective деепричастие form does not exist: many monosyllabic verbs (бить, петь, есть, пить, спать, ждать…) and писать, хотеть, ехать, бежать, искать, казаться. \"While driving he…\" is rendered: Когда он ехал… Ждать and хотеть are replaced with ожидать and желать: *Ожидая гостей… Не желая работать…* For possession, the деепричастие имея is used: *Имея большой опыт, он всегда получает хорошую работу.*"),
  H("Incorrect uses"),
  P("It is incorrect to replace the subordinate clause with a деепричастие phrase: a) if the main and subordinate clauses have different grammatical subjects: *Когда Смит готовил уроки, у него заболела голова* (not «Готовя уроки, у Смита заболела голова»); b) if the main clause is impersonal; c) if the main clause is in the passive voice: *Когда он управлял в пьяном виде машиной, он был арестован.*"),
  NOTE("DLI, Lessons 100 and 102."),
], exercises=[
  FILL("(они) читают → ___", ["читая"], SRC + ", Lesson 100."),
  FILL("(они) говорят → ___", ["говоря"], SRC + ", Lesson 100."),
  MC("(они) служат →", ["служя", "служа"], 1, "-а after ж, ч, ш, щ. " + SRC + ", Lesson 100."),
  FILL("(они) идут → ___", ["идя"], SRC + ", Lesson 100."),
  MC("узнавать →", ["узная", "узнавая"], 1, "Derivatives of -знавать form it from the infinitive. " + SRC + ", Lesson 100."),
  MC("(они) бреются →", ["бреяся", "бреясь"], 1, "-сь (never -ся!). " + SRC + ", Lesson 100."),
  FILL("___ мне это, она плакала. (рассказывать)", ["Рассказывая"], SRC + ", Lesson 100."),
  FILL("___ из дома, я услышал выстрел. (выходить)", ["Выходя"], SRC + ", Lesson 100."),
  FILL("___ так мало, вы не выдержите экзамена. (заниматься)", ["Занимаясь"], SRC + ", Lesson 100."),
  FILL("___ доктором — being a doctor (быть)", ["Будучи"], SRC + ", Lesson 102."),
  MC("Когда она ждёт гостей… →", ["Ждя гостей…", "Ожидая гостей…"], 1, "ждать is replaced with ожидать. " + SRC + ", Lesson 102."),
  FILL("___ большой опыт, он всегда получает хорошую работу. (иметь)", ["Имея"], SRC + ", Lesson 102."),
  MC("Which is correct?", ["Готовя уроки, у Смита заболела голова.", "Когда Смит готовил уроки, у него заболела голова."], 1, "Different grammatical subjects: a деепричастие cannot be used. " + SRC + ", Lesson 102."),
]),

SEC("f9-gerund-perfective", "Perfective деепричастия: прочитав, придя", sub="DLI Lessons 101–103 · -в, -вши · -вшись · -я from -ти verbs · as prepositions", blocks=[
  P("The perfective деепричастие denotes a completed action which precedes the action expressed by the verb which it modifies. Когда, meaning после того как, is replaced by the perfective деепричастие; когда, meaning в то время как, by the imperfective. The деепричастие and the verb it modifies must always have the same actor, and regardless of tense or aspect the деепричастие remains the same."),
  H("Formation"),
  P("The perfective деепричастие is formed from the masculine past tense of the perfective verb by replacing -л with -в or -вши (the -вши form is becoming more and more obsolete): написал — написав (написавши); получил — получив (получивши). Verbs in -ся drop -лся and add -вшись: помылся — помывшись; оделся — одевшись. Perfective verbs ending in -ти (войти, принести) form it from the 3rd person plural future by dropping -ут and adding -я: выйдут — выйдя; принесут — принеся. Where the past tense does not end in -л: погиб — погибши; постригся — постригшись; спасти — спасши; вырасти — выросши."),
  H("Into English"),
  EX(("Получив деньги, он купил телевизор.", "Having received the money (After he had received the money), he bought a television set."), ("Читая книгу, он заснул.", "While reading…"), ("Прочитав книгу, он заснул.", "Having read…"), ("Проходя мимо, он мне что-то крикнул.", "While passing by…"), ("Пройдя мимо, он мне что-то крикнул.", "Having passed by…")),
  P("Do not confuse the деепричастие «написавши» with the past active participle «написавший»: *Написавши эту книгу, он стал известен всему миру. Профессор, написавший курс русской истории, большой специалист в этой области.*"),
  H("деепричастия as prepositions"),
  T(["", ""], [["благодаря + Dat.", "thanks to"], ["включая + Acc.", "including"], ["начиная с + Gen.", "starting (with)"], ["кончая + Instr.", "ending (with)"]], row_heads=False),
  EX(("Я устроился на работу благодаря ему.", "")),
  NOTE("DLI, Lessons 101–103."),
], exercises=[
  FILL("написал → ___", ["написав", "написавши"], SRC + ", Lesson 101."),
  FILL("получил → ___", ["получив", "получивши"], SRC + ", Lesson 101."),
  FILL("помылся → ___", ["помывшись"], SRC + ", Lesson 101."),
  FILL("оделся → ___", ["одевшись"], SRC + ", Lesson 101."),
  MC("выйти (выйдут) →", ["выйдя", "вышедши", "выйдв"], 0, "-ти verbs: from the 3rd pers. plural future + -я. " + SRC + ", Lesson 101."),
  FILL("принести (принесут) → ___", ["принеся"], SRC + ", Lesson 101."),
  FILL("___ деньги, он купил телевизор. (получить)", ["Получив"], SRC + ", Lesson 101."),
  MC("Having read the book, he fell asleep.", ["Читая книгу, он заснул.", "Прочитав книгу, он заснул."], 1, "A completed action preceding the main one. " + SRC + ", Lesson 101."),
  MC("While passing by, he shouted something to me.", ["Проходя мимо, он мне что-то крикнул.", "Пройдя мимо, он мне что-то крикнул."], 0, SRC + ", Lesson 101."),
  FILL("погиб → ___", ["погибши"], SRC + ", Lesson 102."),
  MC("Профессор, ___ курс русской истории, большой специалист.", ["написавши", "написавший"], 1, "The past active participle modifies a noun; the деепричастие does not. " + SRC + ", Lesson 103."),
  FILL("Я устроился на работу ___ ему. — thanks to him", ["благодаря"], SRC + ", Lesson 103."),
]),

]
